-- PanoplySuite_QuestData: Panoply Suite's own quest / NPC / object / item database (data add-on).
-- Records are generated by Panoply Suite's tools/build_questdata.py from the VMaNGOS world database
-- (GPL-2.0-or-later) and stored as plain '|'-separated strings; this file decodes a record the first time it is
-- asked for and caches the result (the raw string is then dropped). Plain Lua, no obfuscation.
-- Distributed under the GNU GPL v3, see LICENSE and NOTICE.md.
local DB = {}
_G.PanoplySuiteQuestData = DB

DB.apiVersion = 1
DB.version = "0.5.9"
DB.source = "VMaNGOS world DB (GPL-2.0-or-later), patch 1.12"
DB.Q, DB.N, DB.O, DB.I = {}, {}, {}, {}      -- filled by Data/*.lua
DB.rects, DB.foreverRects, DB.areaToMap = {}, {}, {}
DB.instanceAreas, DB.instanceMaps, DB.hidden = {}, {}, {}
DB.overlay = { forever = { npcs = {}, objects = {}, notes = {} } }
-- Playable race bits (client ChrRaces.PlayableRaceBit). Classic races use bit = raceID - 1.
DB.raceBits = { [1] = 0, [2] = 1, [3] = 2, [4] = 3, [5] = 4, [6] = 5, [7] = 6, [8] = 7 }
DB.raceSide = { [1] = "A", [3] = "A", [4] = "A", [7] = "A", [2] = "H", [5] = "H", [6] = "H", [8] = "H" }

-- Decoded records live in weak caches: the game's garbage collector drops records nobody holds,
-- and the compact source string is decoded again on the next read. The adapter keeps its own
-- small caches of what the route needs.
local WEAK = { __mode = "v" }
local cQ, cN, cO, cI = setmetatable({}, WEAK), setmetatable({}, WEAK), setmetatable({}, WEAK), setmetatable({}, WEAK)
local tonumber, sub, find, floor = tonumber, string.sub, string.find, math.floor

local function split(s, sep)
  local out, pos = {}, 1
  while true do
    local a = find(s, sep, pos, true)
    if not a then out[#out + 1] = sub(s, pos) return out end
    out[#out + 1] = sub(s, pos, a - 1)
    pos = a + 1
  end
end
DB.Split = split

local function num(s) return tonumber(s) or 0 end
local function ids(s)
  local out = {}
  if s == nil or s == "" then return out end
  for _, v in ipairs(split(s, ",")) do local n = tonumber(v) if n then out[#out + 1] = n end end
  return out
end
local function idCounts(s) -- "id:count,..." -> { {id, count}, ... } or nil
  if s == nil or s == "" then return nil end
  local out = {}
  for _, e in ipairs(split(s, ",")) do
    local p = split(e, ":")
    local id = tonumber(p[1])
    if id then out[#out + 1] = { id, tonumber(p[2]) } end
  end
  return #out > 0 and out or nil
end
local function idPair(s)
  if s == nil or s == "" then return nil end
  local p = split(s, ":")
  return { num(p[1]), num(p[2]) }
end

-- "<uiMap>:<xxxyyy...>;-<instanceMap>" -> { [uiMap] = { {x, y}, ... }, [-map] = { {-1, -1} } } (x, y in 0..100)
local function spawns(s)
  local out = {}
  if s == nil or s == "" then return out end
  for _, seg in ipairs(split(s, ";")) do
    local c = find(seg, ":", 1, true)
    if c then
      local m, pts, list = tonumber(sub(seg, 1, c - 1)), sub(seg, c + 1), {}
      for i = 1, #pts - 5, 6 do
        local x, y = tonumber(sub(pts, i, i + 2), 16), tonumber(sub(pts, i + 3, i + 5), 16)
        if x and y then list[#list + 1] = { x / 40.95, y / 40.95 } end
      end
      if m then out[m] = list end
    else
      local m = tonumber(seg)
      if m then out[m] = { { -1, -1 } } end
    end
  end
  return out
end
DB.DecodeSpawns = spawns

local function killCredit(s) -- "a+b+c:root:count;..." -> { { {a,b,c}, root, nil, count }, ... }
  if s == nil or s == "" then return nil end
  local out = {}
  for _, e in ipairs(split(s, ";")) do
    local p = split(e, ":")
    local list = {}
    for _, v in ipairs(split(p[1] or "", "+")) do local n = tonumber(v) if n then list[#list + 1] = n end end
    if #list > 0 then out[#out + 1] = { list, tonumber(p[2]), nil, tonumber(p[3]) } end
  end
  return #out > 0 and out or nil
end

local function decodeQuest(id, raw)
  local f = split(raw, "|")
  local trig = f[26] ~= "" and spawns(f[26]) or nil
  local q = {
    name = f[1], questLevel = num(f[2]), requiredLevel = num(f[3]), requiredMaxLevel = num(f[4]),
    requiredRaces = num(f[5]), requiredClasses = num(f[6]), zoneOrSort = num(f[7]), questType = num(f[8]),
    questFlags = num(f[9]), specialFlags = num(f[10]),
    startedBy = { ids(f[11]), ids(f[12]), ids(f[13]) },
    finishedBy = { ids(f[14]), ids(f[15]) },
    preQuestSingle = ids(f[16]), preQuestGroup = ids(f[17]), exclusiveTo = ids(f[18]),
    nextQuestInChain = num(f[19]), breadcrumbForQuestId = num(f[20]),
    objectives = { idCounts(f[21]), idCounts(f[22]), idCounts(f[23]), idCounts(f[24]), killCredit(f[25]) },
    triggerEnd = trig and next(trig) and { nil, trig } or nil,
    requiredSkill = idPair(f[27]), requiredMinRep = idPair(f[28]),
    xp = num(f[29]) > 0 and num(f[29]) or nil, sourceItemId = num(f[30]), parentQuest = num(f[31]),
    suggestedPlayers = num(f[32]),
    objectivesText = f[33] ~= "" and { f[33] } or nil,
  }
  return q
end

local function decodeNpc(id, raw)
  local f = split(raw, "|")
  return { name = f[1], subName = f[2] ~= "" and f[2] or nil, minLevel = num(f[3]), maxLevel = num(f[4]),
           rank = num(f[5]), friendlyToFaction = f[6], npcFlags = num(f[7]), spawns = spawns(f[8]) }
end
local function decodeObject(id, raw)
  local f = split(raw, "|")
  return { name = f[1], type = num(f[2]), spawns = spawns(f[3]) }
end
local function decodeItem(id, raw)
  local f = split(raw, "|")
  return { name = f[1], npcDrops = ids(f[2]), objectDrops = ids(f[3]), vendors = ids(f[4]) }
end

local function getter(raw, cache, decode)
  return function(id)
    local c = cache[id]
    if c ~= nil then return c or nil end
    local r = raw[id]
    if type(r) ~= "string" then cache[id] = false return nil end
    local ok, v = pcall(decode, id, r)
    if not ok then cache[id] = false DB.badRecords = (DB.badRecords or 0) + 1 return nil end
    cache[id] = v
    return v
  end
end
DB.Quest = getter(DB.Q, cQ, decodeQuest)
DB.Npc = getter(DB.N, cN, decodeNpc)
DB.Object = getter(DB.O, cO, decodeObject)
DB.Item = getter(DB.I, cI, decodeItem)

local function keys(t)
  local out = {}
  for k in pairs(t) do out[#out + 1] = k end
  table.sort(out)
  return out
end
local idLists = {}
function DB.QuestIds() idLists.Q = idLists.Q or keys(DB.Q) return idLists.Q end
function DB.NpcIds() idLists.N = idLists.N or keys(DB.N) return idLists.N end
function DB.ObjectIds() idLists.O = idLists.O or keys(DB.O) return idLists.O end

local byName
function DB.ObjectIdsByName(name)
  if not byName then
    byName = {}
    for _, id in ipairs(DB.ObjectIds()) do
      local o = DB.Object(id)
      if o then byName[o.name] = byName[o.name] or {} table.insert(byName[o.name], id) end
    end
  end
  return byName[name] or {}
end

-- Decoded-record counts (for memory reports and tests).
-- Location facts (Data/Locations.lua): "kind|name|floor|entrance" per NPC / object id.
-- kind "i" inside a named building, "n" near one; floor "u" upstairs, "d" downstairs; entrance
-- "uiMap:x:y" in percent. Panoply Suite composes the words at runtime (localisable).
DB.LocN, DB.LocO = DB.LocN or {}, DB.LocO or {}
local cL = setmetatable({}, WEAK)
function DB.Location(kind, id)
  local t = (kind == "object") and DB.LocO or DB.LocN
  local raw = type(id) == "number" and t[id]
  if type(raw) ~= "string" then return nil end
  local key = kind .. id
  if cL[key] then return cL[key] end
  local f = split(raw, "|")
  local k = f[1]
  if k ~= "i" and k ~= "n" then return nil end
  local e
  if f[4] and f[4] ~= "" then
    local m, x, y = f[4]:match("^(%d+):([%d%.]+):([%d%.]+)$")
    if m then e = { map = tonumber(m), x = tonumber(x) / 100, y = tonumber(y) / 100 } end
  end
  local v = { indoor = k == "i", near = k == "n", name = (f[2] ~= "" and f[2]) or nil,
              floor = (f[3] == "u" and 1) or (f[3] == "d" and -1) or nil, entrance = e }
  cL[key] = v
  return v
end

function DB.Stats()
  local function n(t) local c = 0 for _, v in pairs(t) do if v then c = c + 1 end end return c end
  return { quests = #DB.QuestIds(), npcs = #DB.NpcIds(), objects = #DB.ObjectIds(),
           decodedQuests = n(cQ), decodedNpcs = n(cN), decodedObjects = n(cO), decodedItems = n(cI) }
end

-- Hidden quests (disabled, event-only or placeholder records): never routed.
function DB.IsHidden(id)
  if not DB.hiddenSet then
    DB.hiddenSet = {}
    for _, q in ipairs(DB.hidden) do DB.hiddenSet[q] = true end
  end
  return DB.hiddenSet[id] == true
end

-------------------------------------------------------------------------------
-- Map geometry. Stored spawn percents are on the Era zone rectangles (DB.rects). A client whose
-- rectangle for a zone differs (WoW Forever re-drew some zones) gets the same world point
-- re-expressed on its own rectangle. The world position itself is the Era server position: where an
-- NPC really stands on Forever is only known once a player has seen it there (see the adapter).
-------------------------------------------------------------------------------
local function toWorld(r, px, py) return r[4] - py * (r[4] - r[2]), r[5] - px * (r[5] - r[3]) end
local function toPercent(r, wx, wy) return (r[5] - wy) / (r[5] - r[3]), (r[4] - wx) / (r[4] - r[2]) end
DB.ToWorld, DB.ToPercent = toWorld, toPercent

-- uiMap, x, y (0..1, Era rectangle) -> x, y (0..1) on the given rectangle set, or nil when the point
-- falls outside the zone there.
function DB.Reproject(m, x, y, rectSet)
  local from, to = DB.rects[m], rectSet and rectSet[m]
  if not from or not to then return x, y end
  local wx, wy = toWorld(from, x, y)
  local nx, ny = toPercent(to, wx, wy)
  if nx < 0 or nx > 1 or ny < 0 or ny > 1 then return nil end
  return nx, ny
end
